// Generated by scripts/sync-docker-env-example.mjs from docker/.env.example. Do not edit.
export const DOCKER_ENV_EXAMPLE =
  '# Celune self-host stack: environment for docker/docker-compose.yml\n#\n# Easiest path: run `npx @celuneai/cli init --mode docker` from the repo root. It\n# copies this file to docker/.env and fills every secret below with\n# crypto-random values (it never prints them).\n#\n# Manual path: copy this file to docker/.env and fill each <generate> value.\n#   hex 32 bytes:   openssl rand -hex 32\n#   base64 48:      openssl rand -base64 48\n#   ANON_KEY / SERVICE_ROLE_KEY are HS256 JWTs signed with JWT_SECRET:\n#     payload {"role":"anon","iss":"supabase","iat":<now>,"exp":<now + 10 years>}\n#     payload {"role":"service_role","iss":"supabase","iat":<now>,"exp":<now + 10 years>}\n#   `npx @celuneai/cli init` produces both; the Supabase self-hosting guide has a generator too.\n#\n# Never commit docker/.env. It is gitignored and excluded from Docker builds.\n\n# ── Edition ────────────────────────────────────────────────────────────────\n# The compose file pins CELUNE_EDITION=community for api and web: no billing,\n# no plan limits, no Stripe, BYOK-only AI (each workspace adds its own keys\n# in Settings > Provider Keys).\n\n# ── Public URLs and ports ──────────────────────────────────────────────────\nSITE_URL=http://localhost:3000\nSUPABASE_PUBLIC_URL=http://localhost:8000\nAPP_DOMAIN=localhost\nSUPPORT_EMAIL=admin@localhost\nWEB_PORT=3000\nAPI_PORT=3010\nKONG_HTTP_PORT=8000\nPOSTGRES_HOST_PORT=54322\nSTUDIO_PORT=54323\n\n# ── Supabase secrets ───────────────────────────────────────────────────────\n# Generate: openssl rand -hex 32\nPOSTGRES_PASSWORD=\n# Generate: openssl rand -hex 32\nJWT_SECRET=\n# Token lifetime in seconds.\nJWT_EXPIRY=3600\n# Generate: HS256 JWT, role anon, signed with JWT_SECRET\nANON_KEY=\n# Generate: HS256 JWT, role service_role, signed with JWT_SECRET\nSERVICE_ROLE_KEY=\n# Generate: openssl rand -base64 48\nSECRET_KEY_BASE=\n# Realtime encrypts its tenant settings with this key. It must be exactly 16\n# characters. Generate: openssl rand -hex 8\nREALTIME_DB_ENC_KEY=\n\n# ── Auth ───────────────────────────────────────────────────────────────────\n# Email sign-in confirms accounts without mail by default so the first user\n# can sign in. Set to false and fill SMTP_* to require confirmation.\nENABLE_EMAIL_AUTOCONFIRM=true\n# Open sign-up is off, so strangers who reach the stack cannot create\n# accounts. Create the first account as SETUP.md describes. Set to false only\n# while people you trust sign up, then set it back and restart auth.\nDISABLE_SIGNUP=true\nADDITIONAL_REDIRECT_URLS=\nAUTH_PROVIDERS=email\nSMTP_ADMIN_EMAIL=\nSMTP_HOST=\nSMTP_PORT=587\nSMTP_USER=\nSMTP_PASS=\nSMTP_SENDER_NAME=\n\n# ── Celune secrets ─────────────────────────────────────────────────────────\n# AES-256-GCM key for workspace provider keys (BYOK) and job payloads.\n# Generate: openssl rand -hex 32\nPROVIDER_KEY_ENCRYPTION_KEY=\n# HMAC-SHA256 key that signs job queue rows. The web and api services must share it.\n# Until it is set, jobs are signed with a subkey of PROVIDER_KEY_ENCRYPTION_KEY, and\n# jobs signed that way still verify for one release after you set it.\n# Generate: openssl rand -hex 32\nJOB_HMAC_KEY=\n# AES-256-GCM key for stored integration credentials.\n# Generate: openssl rand -hex 32\nCREDENTIAL_ENCRYPTION_KEY=\n# HS256 secret for host-minted JWTs accepted by /v1 and /v1/mcp. The api and\n# web services refuse to start when it is shorter than 32 bytes.\n# Generate: openssl rand -hex 32\nCELUNE_HOST_JWT_SECRET=\n# Optional. A JWKS URL for host tokens signed with an asymmetric key, used with or\n# instead of CELUNE_HOST_JWT_SECRET.\nCELUNE_HOST_JWKS_URL=\n# Optional. When set, host tokens must carry this iss and aud. The web service signs\n# embed tokens with them and the api service checks them, so compose passes the same\n# values to both.\nCELUNE_HOST_JWT_ISSUER=\nCELUNE_HOST_JWT_AUDIENCE=\n# AES-256-GCM key for bot token encryption.\n# Generate: openssl rand -hex 32\nWEBHOOK_ENCRYPTION_KEY=\n# Shared secrets for cron and hook endpoints.\n# Generate: openssl rand -hex 32\nCRON_SECRET=\n# Generate: openssl rand -hex 32\nHOOK_SECRET=\n# Prefix for the API keys this install issues.\nCELUNE_API_KEY_PREFIX=celune\n';
